// compute the ALU result, zero flag, and overflow flag
// Supports: ADD, SUB, AND, OR, XOR, SLL, SRL, SLT, SLTU, SRA, A+4, B-passthrough
reg[31:0] res_r;
always @(*) begin
    case (Control)
        ALU_ADD:  res_r = A + B;
        ALU_SUB:  res_r = A - B;
        ALU_AND:  res_r = A & B;
        ALU_OR:   res_r = A | B;
        ALU_XOR:  res_r = A ^ B;
        ALU_SLL:  res_r = A << shamt;
        ALU_SRL:  res_r = A >> shamt;
        ALU_SLT:  res_r = ($signed(A) < $signed(B)) ? 32'd1 : 32'd0;
        ALU_SLTU: res_r = (A < B) ? 32'd1 : 32'd0;
        ALU_SRA:  res_r = $signed(A) >>> shamt;
        ALU_Ap4:  res_r = A + 32'd4;
        ALU_Bout: res_r = B;
        default:  res_r = 32'b0;
    endcase
end

assign res = res_r;
assign zero = ~|res_r;
assign overflow = (Control == ALU_ADD) ? (A[31] == B[31] && res_r[31] != A[31]) :
                  (Control == ALU_SUB) ? (A[31] != B[31] && res_r[31] != A[31]) :
