wire valid = R_valid | I_valid | B_valid | L_valid | S_valid | CSR_valid |
             LUI | AUIPC | JAL | JALR | ECALL | MRET;
wire illegal = ~valid;

assign Branch = (B_valid & cmp_res) | JAL | JALR;

assign ImmSel = (Iop | Lop | JALR) ? 3'b001 :     // I-type
                Bop              ? 3'b010 :     // B-type
                JAL              ? 3'b011 :     // J-type
                Sop              ? 3'b100 :     // S-type
                (LUI | AUIPC)    ? 3'b101 :     // U-type
                3'b000;

assign cmp_ctrl = BEQ  ? 3'b001 :
                  BNE  ? 3'b010 :
                  BLT  ? 3'b011 :
                  BLTU ? 3'b100 :
                  BGE  ? 3'b101 :
                  BGEU ? 3'b110 : 3'b000;

assign ALUSrc_A = AUIPC | JAL | JALR;   // 1: PC, 0: rs1
assign ALUSrc_B = I_valid | L_valid | S_valid | LUI | AUIPC | JAL | JALR; // 1: Imm, 0: rs2

assign ALUControl = (ADD | ADDI | L_valid | S_valid | AUIPC) ? 4'b0001 :
                    SUB          ? 4'b0010 :
                    (AND | ANDI) ? 4'b0011 :
                    (OR  | ORI)  ? 4'b0100 :
                    (XOR | XORI) ? 4'b0101 :
                    (SLL | SLLI) ? 4'b0110 :
                    (SRL | SRLI) ? 4'b0111 :
                    (SLT | SLTI) ? 4'b1000 :
                    (SLTU|SLTIU) ? 4'b1001 :
                    (SRA | SRAI) ? 4'b1010 :
                    (JAL | JALR) ? 4'b1011 :   // A + 4 (link address)
                    LUI          ? 4'b1100 :   // B passthrough
                    4'b0000;

assign DatatoReg = L_valid | CSR_valid; // 1: memory/CSR data, 0: ALU result
assign RegWrite = R_valid | I_valid | L_valid | CSR_valid | LUI | AUIPC | JAL | JALR;
