// ---------------- exception handling logic ----------------
// synchronous exceptions are raised when the faulting instruction reaches WB;
// interrupt is external and refers to the next instruction to execute
wire sync_exc = illegal_inst | ecall_m | l_access_fault | s_access_fault;
wire interrupt_en = interrupt & mstatus[3];     // mstatus.MIE
wire trap = sync_exc | interrupt_en;

// mcause: illegal=2, l_access_fault=5, s_access_fault=7, ecall=11,
//         machine external interrupt=0x8000000b
reg[31:0] cause;
always @(*) begin
    if (illegal_inst)         cause = 32'd2;
    else if (ecall_m)         cause = 32'd11;
    else if (l_access_fault)  cause = 32'd5;
    else if (s_access_fault)  cause = 32'd7;
    else                      cause = 32'h8000000b;
end

// mepc: faulting instruction for sync exceptions, next PC for interrupt
wire[31:0] mepc_in = sync_exc ? epc_cur : epc_next;
// mtval: no faulting instruction/address information is available
// through the fixed ports of this unit, so it is written as 0
wire[31:0] mtval_in = 32'b0;

// trap entry:  MPP <- 11, MPIE <- MIE, MIE <- 0
wire[31:0] mstatus_trap = {mstatus[31:13], 2'b11, mstatus[10:8],
                           mstatus[3], mstatus[6:4], 1'b0, mstatus[2:0]};
// mret:        MPP <- 00, MPIE <- 1, MIE <- MPIE
wire[31:0] mstatus_mret = {mstatus[31:13], 2'b00, mstatus[10:8],
                           1'b1, mstatus[6:4], mstatus[7], mstatus[2:0]};

// On a trap several CSRs must be updated through the single write port:
// mepc is written in the detection cycle, then a small FSM writes
// mcause, mtval and mstatus in the following three cycles. The trap
// handler reaches MEM at least 4 cycles after the redirect, so all
// values are in place before they can be read.
localparam ST_IDLE    = 3'd0;
localparam ST_MCAUSE  = 3'd1;
localparam ST_MTVAL   = 3'd2;
localparam ST_MSTATUS = 3'd3;

reg[2:0] state;
reg[31:0] saved_cause, saved_mtval, saved_mstatus;

// CSR read address: trap -> mtvec, mret -> mepc, otherwise the
// address of the CSR instruction currently in MEM
assign csr_raddr = trap ? 12'h305 :
                   mret ? 12'h341 : csr_rw_addr_in;
assign csr_r_data_out = csr_rdata;

// PC redirect: trap -> mtvec, mret -> mepc (both via csr_rdata)
assign PC_redirect = csr_rdata;
assign redirect_mux = trap | mret;

// pipeline flush: a trap kills every in-flight instruction (the one in
// WB is cancelled below); mret only kills the younger wrong-path ones
assign reg_FD_flush = trap | mret;
assign reg_DE_flush = trap | mret;
assign reg_EM_flush = trap | mret;
assign reg_MW_flush = trap;
assign RegWrite_cancel = trap;
assign MemWrite_cancel = trap;

// normal CSR instruction write (MEM stage). For set/clear modes a zero
// source (rs1 = x0 / uimm = 0) must not modify the CSR.
wire csr_w_normal = csr_rw_in & ~(csr_wsc_mode_in[1] & (csr_w_data_imm == 5'b0));
wire[31:0] csr_wdata_normal = csr_w_imm_mux ? {27'b0, csr_w_data_imm} : csr_w_data_reg;

// CSR write port mux: trap/FSM/mret have priority over normal CSR writes
always @(*) begin
    if (trap) begin
        csr_w = 1'b1; csr_waddr = 12'h341; csr_wdata = mepc_in; csr_wsc = 2'b01;
    end
    else if (state == ST_MCAUSE) begin
        csr_w = 1'b1; csr_waddr = 12'h342; csr_wdata = saved_cause; csr_wsc = 2'b01;
    end
    else if (state == ST_MTVAL) begin
        csr_w = 1'b1; csr_waddr = 12'h343; csr_wdata = saved_mtval; csr_wsc = 2'b01;
    end
    else if (state == ST_MSTATUS) begin
        csr_w = 1'b1; csr_waddr = 12'h300; csr_wdata = saved_mstatus; csr_wsc = 2'b01;
    end
    else if (mret) begin
        csr_w = 1'b1; csr_waddr = 12'h300; csr_wdata = mstatus_mret; csr_wsc = 2'b01;
    end
    else begin
        csr_w = csr_w_normal; csr_waddr = csr_rw_addr_in;
        csr_wdata = csr_wdata_normal; csr_wsc = csr_wsc_mode_in;
    end
end

always @(posedge clk or posedge rst) begin
    if (rst) begin
        state <= ST_IDLE;
        saved_cause <= 0;
        saved_mtval <= 0;
        saved_mstatus <= 0;
    end
    else if (trap) begin
        state <= ST_MCAUSE;
        saved_cause <= cause;
        saved_mtval <= mtval_in;
        saved_mstatus <= mstatus_trap;
    end
    else if (state == ST_MCAUSE)  state <= ST_MTVAL;
    else if (state == ST_MTVAL)   state <= ST_MSTATUS;
    else if (state == ST_MSTATUS) state <= ST_IDLE;
end

