`timescale 1ns / 1ps

module tb_lab2;
    reg clk, rst;
    integer cycle;
    integer trap_count;

    RV32core core(
        .debug_en(1'b0),
        .debug_step(1'b0),
        .debug_addr(7'b0),
        .debug_data(),
        .clk(clk),
        .rst(rst),
        .wb_pc(),
        .wb_inst(),
        .mem_addr(),
        .mem_data(),
        .interrupter(1'b0)
    );

    initial begin
        clk = 0;
        rst = 1;
        cycle = 0;
        trap_count = 0;
        #3 rst = 0;
    end
    always #1 clk = ~clk;

    // watch WB-stage register write-backs
    always @(posedge clk) begin
        if (!rst) begin
            cycle = cycle + 1;
            if (core.RegWrite_WB && !core.RegWrite_cancel_exp && core.rd_WB != 0)
                $display("[cyc %0d] WB: PC=%h  x%0d <= %h", cycle, core.PC_WB, core.rd_WB, core.wt_data_WB);
            if (core.redirect_mux_exp) begin
                if (core.exp_unit.trap) begin
                    trap_count = trap_count + 1;
                    $display("[cyc %0d] TRAP #%0d taken: redirect PC=%h (mtvec), fault PC_WB=%h",
                             cycle, trap_count, core.PC_redirect_exp, core.PC_WB);
                end
                else
                    $display("[cyc %0d] MRET: redirect PC=%h (mepc)", cycle, core.PC_redirect_exp);
            end
            if (cycle == 900) begin
                $display("---- final architectural state ----");
                $display("x1 =%h  x2 =%h  x4 =%h  x5 =%h",
                    core.register.register[1], core.register.register[2],
                    core.register.register[4], core.register.register[5]);
                $display("x6 =%h  x7 =%h", core.register.register[6], core.register.register[7]);
                $display("x25=%h  x27=%h  x28=%h  x29=%h  x30=%h",
                    core.register.register[25], core.register.register[27],
                    core.register.register[28], core.register.register[29],
                    core.register.register[30]);
                $display("mstatus=%h mtvec=%h CSR6=%h mepc=%h mcause=%h mtval=%h mip=%h",
                    core.exp_unit.csr.CSR[0], core.exp_unit.csr.CSR[5],
                    core.exp_unit.csr.CSR[6], core.exp_unit.csr.CSR[9],
                    core.exp_unit.csr.CSR[10], core.exp_unit.csr.CSR[11],
                    core.exp_unit.csr.CSR[12]);
                $display("total traps taken: %0d", trap_count);
                $finish;
            end
        end
    end
endmodule
